    "ನಿಮ್ಮ ದೈನಂದಿನ ಮಾತ್ರೆಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ...",
    "ನಿಮಗೆ ತಿಳಿದಿರುವ ಯಾವುದೇ ಅಲರ್ಜಿಗಳಿವೆಯೇ?",
