export function translatePreConsultation(languageCode: string, source: string): string {
  const index = PRECONSULT_SOURCE_STRINGS.indexOf(source as typeof PRECONSULT_SOURCE_STRINGS[number]);
  if (index < 0 || languageCode === "en") return source;
  return PRECONSULT_TRANSLATIONS[languageCode]?.[index] ?? source;
}

const SOURCE_BY_TRANSLATION = new Map<string, string>();
for (const [languageCode, translations] of Object.entries(PRECONSULT_TRANSLATIONS)) {
  translations.forEach((translation, index) => {
    const source = PRECONSULT_SOURCE_STRINGS[index];
    if (source && translation) SOURCE_BY_TRANSLATION.set(translation, source);
  });
  if (languageCode === "en") {
    PRECONSULT_SOURCE_STRINGS.forEach((source) => SOURCE_BY_TRANSLATION.set(source, source));
  }
}

export function resolvePreConsultationSource(value: string): string | undefined {
  return SOURCE_BY_TRANSLATION.get(value);
}
